// A Verilator argument file that ties generated SV to a hand-written testbench outside
// sv-examples/, such as verilatorTB/tb_APB_to_Memory.sv. Everything else under sv-examples/ is
// linted by naming its top file with USE_INCLUDES: each generated file, and each hand-written one
// a test writes there, includes what it needs (ts/test/models/guardSV.ts). A testbench outside
// sv-examples/ can't be found that way, so its filelist names it with the generated files it
// instantiates, and `scripts/lint-sv.sh` lints the filelist with `verilator --lint-only -F`,
// never those files alone. The filelist defines USE_INCLUDES and puts its own directory on the
// include path, so each generated file it names brings in the files that one includes.
import { writeFileSync } from 'fs'
import { posix } from 'path'

/**
 * Writes `<dir>/<top>.f`. `files` are relative to `dir`, as `-F` reads them; a file outside
 * sv-examples/, such as a hand-written testbench in verilatorTB/, is named relative to `dir` too.
 * Name only the top file of each generated design: its includes bring in the rest.
 */
export function writeLintFilelist (dir: string, top: string, files: string[], generator: string): void {
  const lines = [
    `// Generated by ${generator}. Lints ${top} with the files it depends on:`,
    `//   verilator --lint-only -F ${posix.join(dir, `${top}.f`)}`,
    `--top-module ${top}`,
    '+define+USE_INCLUDES',
    '+incdir+.',
    ...files
  ]
  writeFileSync(posix.join(dir, `${top}.f`), lines.join('\n') + '\n')
}
